package glitch

import data.glitch_lib

sensitive_pattern := "(?i)(password|secret|passphrase|token|key|credential|auth|secretValue|credentialBase64|adminPassword|masterKey|sharedKey|connectionString|defaultPassword|initialPassword|loginCredential|encryptionKey|privateKey|secretKey|symmetricKey|apiKey|apiToken|bearerToken|serviceAccountKey|defaultAdmin|rootPassword|guestPassword)"

find_sensitive_in_complex(node, path) = results {
    node.ir_type == "Hash"
    results := {r |
        pair := node.value[_]
        key := pair.key
        value := pair.value
        key.ir_type == "String"
        regex.match(sensitive_pattern, key.value)
        value.ir_type == "String"
        not glitch_lib.traverse_var(value)
        r := {
            "type": "sec_hard_secr",
            "element": key,
            "path": path,
            "description": "Hard-coded credential detected. (CWE-798)"
        }
    } | {r |
        pair := node.value[_]
        value := pair.value
        value.ir_type in {"Hash", "Array"}
        r := find_sensitive_in_complex(value, path)
    }
}

find_sensitive_in_complex(node, path) = results {
    node.ir_type == "Array"
    results := {r |
        elem := node.value[_]
        elem.ir_type in {"Hash", "Array"}
        r := find_sensitive_in_complex(elem, path)
    }
}

find_sensitive_in_complex(node, path) = results {
    not (node.ir_type in {"Hash", "Array"})
    results := set()
}

